retained_functions.compact:
def compact(d):
    out = {}
    for k,v in d.items():
        if k=='changed_cell_count': out[k]=v
        else:
            out[k]=len(v) if isinstance(v,list) else v
    return out

retained_functions.click_and_diff:
def click_and_diff(row, col):
    r = action([{'action':'MOUSE','row':row,'col':col}])
    d = frame_diff()
    info = {'cell_count': d['changed_cell_count']}
    for k in ('moved','rotated','appeared','disappeared','changed_color','resized'):
        v = d.get(k) or []
        if v: info[k]=v
    tl = last_animation_timeline or {}
    steps = [(s['step'], s.get('bbox'), s.get('changes', s.get('transitions'))) for s in tl.get('steps',[])]
    return r.get('executed'), info, steps, r.get('game_over'), r.get('level_completed')

